#!/usr/bin/env python3
"""Package owner-review artifacts generated by the PHP composition classes."""
from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import subprocess,json,hashlib
BASE=Path(__file__).resolve().parent
review=BASE/'review';review.mkdir(exist_ok=True)
names=['compact','sidebar-round','sidebar-rounded','editorial','strip-above','strip-inline','long','minimal','empty','rebound']
subprocess.run(['pdfunite',*[str(BASE/'pdf'/(n+'.pdf')) for n in names],
 str(review/'H07-Kontaktkompositionen.pdf')],check=True,timeout=30)
with ZipFile(review/'H07-Kontaktkompositionen-ODT.zip','w',ZIP_DEFLATED) as z:
 for n in names:z.write(BASE/(n+'.odt'),n+'.odt')
 for n in ['README.md','BuildingBlocks.php','ContactComposition.php','generate.php','carrier.php','seed.py','lifecycle.php','verify.py','verification.json','phpunit-existing-capabilities.txt']:
  z.write(BASE/n,'Nachweise/'+n)
 for fam in ['lucide','tabler']:
  p=BASE.parent/'native/assets'/(fam+'-LICENSE');z.write(p,'Lizenzen/'+fam+'.txt')
report={p.name:{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in review.iterdir() if p.suffix in ['.pdf','.zip']}
(BASE/'review-checksums.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
